static void CaptureAndCheck(HowToPlayPanel nav,Canvas canvas){actions.HowToPlay();nav.Turn(-1);if(nav.PageIndex!=0)throw new Exception("First page boundary");nav.Turn(99);if(nav.PageIndex!=6||nav.pages.Count(g=>g.activeSelf)!=1)throw new Exception("Last page boundary");nav.Show(2);var camera=canvas.worldCamera;var mode=canvas.renderMode;float plane=canvas.planeDistance;var cam=UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsSortMode.None).First(c=>c.gameObject.scene==actions.gameObject.scene);var old=cam.targetTexture;var active=RenderTexture.active;var rt=new RenderTexture(1920,1080,24);var tex=new Texture2D(1920,1080,TextureFormat.RGB24,false);try{Directory.CreateDirectory(Root+"/Concepts/Refined");canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=cam;canvas.planeDistance=1;cam.targetTexture=rt;for(int page=0;page<7;page++){nav.Show(page);Canvas.ForceUpdateCanvases();cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1920,1080),0,0);tex.Apply();File.WriteAllBytes(Root+"/Concepts/Refined/Page_"+(page+1)+".png",tex.EncodeToPNG());if(page==2)File.WriteAllBytes(Root+"/Concepts/Refined/HowToPlay_Assembled.png",tex.EncodeToPNG());}}finally{cam.targetTexture=old;RenderTexture.active=active;canvas.renderMode=mode;canvas.worldCamera=camera;canvas.planeDistance=plane;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);actions.CloseHow();}}
